import os,json,subprocess,stat,datetime
from pathlib import Path
candidates={
"rea_final":"/home/ubuntu/rea-final-runtime",
"rea_680":"/home/ubuntu/rea-original-upstream-680",
"rea_680_evidence":"/home/ubuntu/rea-original-upstream-680-evidence",
"codex_agent":"/home/ubuntu/codex-agent",
"codex_bridge":"/home/ubuntu/codex-bridge",
"codex_tests":"/home/ubuntu/codex-tests",
"android_sdk":"/opt/android-sdk",
"hopper":"/opt/hopper",
"gradle_root":"/root/.gradle",
"android_root":"/root/.android",
"fadego_web":"/var/www/fadego-preview",
"lowcost_web":"/var/www/lowcost-europa",
"lowcost_data":"/var/lib/lowcost-europa",
"iptvpn_private_etc":"/etc/iptvpn-bot",
"iptvpn_private_root":"/root/project-secrets/iptvpn_bot"}
out={"utc":datetime.datetime.now(datetime.timezone.utc).isoformat(),"checks":{},"disk":{},"service_refs":{},"active_references":{}}
for k,v in candidates.items():
 p=Path(v)
 try:
  s=p.lstat()
  info={"exists":True,"kind":"link" if p.is_symlink() else "directory" if p.is_dir() else "file","uid":s.st_uid,"gid":s.st_gid,"dev":s.st_dev,"inode":s.st_ino}
  if p.is_symlink():info["target"]=os.readlink(v)
  if p.is_dir():
   entries=list(p.iterdir())
   info["entries"]=len(entries)
   info["names"]=[x.name for x in entries if x.name not in ("private","data","secrets",".ssh",".git",".env")][:22]
  out["checks"][k]=info
 except FileNotFoundError:out["checks"][k]={"exists":False}
 except Exception as e:out["checks"][k]={"error":type(e).__name__}
try:
 p=subprocess.run(["df","-B1","/","/srv/projects","/opt"],capture_output=True,text=True,timeout=10)
 out["disk"]={"exit":p.returncode,"lines":p.stdout.splitlines()[:5]}
except Exception as e:out["disk"]={"error":type(e).__name__}
config=[]
for base in ("/etc/systemd/system","/etc/nginx/sites-enabled","/etc/nginx/sites-available"):
 for p in Path(base).glob("*"):
  if p.is_file() and not p.is_symlink() and p.stat().st_size<60000 and p.suffix in (".service",".timer",".conf"):
   config.append(p)
proc_refs={k:[] for k in candidates}
for p in Path("/proc").iterdir():
 if not p.name.isdigit():continue
 try:
  cwd=os.readlink(str(p/"cwd"))
  ex=os.readlink(str(p/"exe"))
  cmd=(p/"cmdline").read_bytes().replace(b"\0",b" ").decode("utf8","replace")[:1200]
  for k,v in candidates.items():
   if cwd.startswith(v+"/") or cwd==v or ex.startswith(v+"/") or v in cmd:
    proc_refs[k].append({"pid":int(p.name),"cwd":cwd[:140],"comm":(p/"comm").read_text().strip()[:60]})
 except Exception:continue
out["active_references"]={k:v[:15] for k,v in proc_refs.items() if v}
for k,v in candidates.items():
 references=[]
 for p in config:
  try:
   if v in p.read_text(errors="ignore"):references.append(str(p))
  except Exception:continue
 if references:out["service_refs"][k]=references
print(json.dumps(out,ensure_ascii=True,separators=(",",":")))
